# Python数据类型：本章综合基础代码
from collections import Counter
def transform(values,fn):
    return [fn(x) for x in values]
print(transform([1,2,3],lambda x:x*x))
try:
    print(1/0)
except ZeroDivisionError:
    print("Dividing by zero was blocked")
print(Counter(["ETF","stock","ETF"]))

